package VitaFortis.demo.v1.controller;
import VitaFortis.demo.v1.dto.*; import VitaFortis.demo.v1.service.AvaliacaoService; import jakarta.validation.Valid; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/v1/produtos/{produtoId}/avaliacoes") public class AvaliacaoController {private final AvaliacaoService service;public AvaliacaoController(AvaliacaoService s){service=s;}@GetMapping public List<AvaliacaoResponseDto> listar(@PathVariable Long produtoId){return service.listar(produtoId);}@PostMapping public AvaliacaoResponseDto criar(@PathVariable Long produtoId,@Valid @RequestBody AvaliacaoRequestDto dto,Authentication auth){return service.criar(produtoId,dto,auth.getName());}}
